create database customer_behavior;
select * from customer_shopping_clean;
alter table cu_b rename to customer;
select * from customer;

-- 1. what is the total revenue generated by male vs female customer ?
select gender, sum(purchase_amount) as total_revenue from customer group by gender;

-- 2. Which customer used a discount but still spent more than the average amount ?
select customer_id, purchase_amount from customer where discount_applied='Yes' and purchase_amount>=(select avg(purchase_amount) from customer);

-- 3. Which are the top 5 products with the highest average review rating ?
select item_purchased,round(avg(review_rating),2) as Review_rating from customer group by item_purchased order by Review_rating desc limit 5;
 
-- 4. Compare the average purchase amount between standard and Express shipping ?
select shipping_type, avg(purchase_amount) from customer where shipping_type in ('Standard','Express') group by shipping_type;

-- 5. Do subscribe customer spents more ? Compare average spents and total revenue between subscriber and un-subscribers.
 select subscription_status, count(customer_id), avg(purchase_amount) as avg_spent,
 sum(purchase_amount) as total_revenue from customer group by subscription_status order by total_revenue,avg_spent;
 
-- 6. Which 5 products have the highest percentage of purchase with discounts applied ?
select item_purchased,sum(case when discount_applied='Yes' then 1 else 0 end)/count(*)*100  as discount_rate
  from customer group by item_purchased order by discount_rate desc limit 5;
  
-- 7. Segment customer into new,Returning and LOyal based on their total number of previous purchase and show the count of each segment;
with customer_type as(select customer_id,previous_purchases, 
case
 when previous_purchases =1 then 'New'
 when previous_purchases between 2 and 10 then 'Returning'
 else 'Loyal'
 end as  customer_segment
 from customer)
 select customer_segment, count(*) as Numberofcustomer from customer_type group by customer_segment;
 
 -- 8. What are the  top 3 most purchased product within each category ?
  with item_counts as (select category, item_purchased, count(customer_id) as total_orders,
 row_number() over(partition by category order by count(customer_id) desc) as item_rank
 from customer
 group by category, item_purchased)
 select item_rank, category, total_orders from item_counts where item_rank<= 3;
 
 -- 9. Are customers who are repeat buyers (More than 5 previous purchases) also likely to subscribe ?
 select subscription_status, count(customer_id) as repeat_buyer from customer where previous_purchases>5 group by subscription_status; 
 
 -- 10. What is the revenue contribution of each age group;
 select age_group, sum(purchase_amount) as total_revenue
 from customer group by age_group order by total_revenue;
 
 